CREATE TABLE IF NOT EXISTS subjects(id SERIAL PRIMARY KEY,name TEXT UNIQUE NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS documents(id SERIAL PRIMARY KEY,subject_id INT NOT NULL REFERENCES subjects ON DELETE CASCADE,filename TEXT,doc_type TEXT,file_type TEXT,file_size BIGINT,method TEXT,sha256 TEXT,status TEXT DEFAULT 'done',created_at TIMESTAMPTZ DEFAULT now(),UNIQUE(subject_id,sha256));
CREATE TABLE IF NOT EXISTS document_pages(id SERIAL PRIMARY KEY,document_id INT NOT NULL REFERENCES documents ON DELETE CASCADE,subject_id INT NOT NULL REFERENCES subjects ON DELETE CASCADE,page_no INT,content TEXT);
CREATE TABLE IF NOT EXISTS document_chunks(id SERIAL PRIMARY KEY,document_id INT NOT NULL REFERENCES documents ON DELETE CASCADE,subject_id INT NOT NULL REFERENCES subjects ON DELETE CASCADE,page_no INT,content TEXT,tsv tsvector GENERATED ALWAYS AS (to_tsvector('english',content)) STORED);
CREATE INDEX IF NOT EXISTS chunks_tsv ON document_chunks USING GIN(tsv);
CREATE INDEX IF NOT EXISTS chunks_subj ON document_chunks(subject_id);
CREATE TABLE IF NOT EXISTS topics(id SERIAL PRIMARY KEY,subject_id INT NOT NULL REFERENCES subjects ON DELETE CASCADE,name TEXT NOT NULL,UNIQUE(subject_id,name));
CREATE TABLE IF NOT EXISTS topic_mastery(topic_id INT PRIMARY KEY REFERENCES topics ON DELETE CASCADE,subject_id INT NOT NULL REFERENCES subjects ON DELETE CASCADE,attempts INT DEFAULT 0,score DOUBLE PRECISION DEFAULT 0,max_score DOUBLE PRECISION DEFAULT 0,last_attempt TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS tests(id SERIAL PRIMARY KEY,subject_id INT NOT NULL REFERENCES subjects ON DELETE CASCADE,title TEXT,difficulty TEXT,question_count INT,topics TEXT,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS questions(id SERIAL PRIMARY KEY,subject_id INT NOT NULL REFERENCES subjects ON DELETE CASCADE,test_id INT NOT NULL REFERENCES tests ON DELETE CASCADE,num INT,text TEXT,marks INT,difficulty TEXT,topic TEXT,qtype TEXT,solution TEXT);
CREATE TABLE IF NOT EXISTS test_questions(test_id INT REFERENCES tests ON DELETE CASCADE,question_id INT REFERENCES questions ON DELETE CASCADE,position INT,PRIMARY KEY(test_id,question_id));
CREATE TABLE IF NOT EXISTS attempts(id SERIAL PRIMARY KEY,subject_id INT NOT NULL REFERENCES subjects ON DELETE CASCADE,test_id INT NOT NULL REFERENCES tests ON DELETE CASCADE,score DOUBLE PRECISION,max_score DOUBLE PRECISION,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS attempt_answers(id SERIAL PRIMARY KEY,attempt_id INT NOT NULL REFERENCES attempts ON DELETE CASCADE,question_id INT NOT NULL REFERENCES questions ON DELETE CASCADE,answer_text TEXT);
CREATE TABLE IF NOT EXISTS transcriptions(id SERIAL PRIMARY KEY,attempt_answer_id INT NOT NULL REFERENCES attempt_answers ON DELETE CASCADE,filename TEXT,text TEXT);
CREATE TABLE IF NOT EXISTS evaluations(id SERIAL PRIMARY KEY,attempt_answer_id INT NOT NULL REFERENCES attempt_answers ON DELETE CASCADE,score DOUBLE PRECISION,max_score DOUBLE PRECISION,feedback JSONB);
CREATE TABLE IF NOT EXISTS evaluation_steps(id SERIAL PRIMARY KEY,evaluation_id INT NOT NULL REFERENCES evaluations ON DELETE CASCADE,step_no INT,text TEXT);
CREATE TABLE IF NOT EXISTS tutor_conversations(id SERIAL PRIMARY KEY,subject_id INT NOT NULL REFERENCES subjects ON DELETE CASCADE,title TEXT,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS tutor_messages(id SERIAL PRIMARY KEY,conversation_id INT NOT NULL REFERENCES tutor_conversations ON DELETE CASCADE,role TEXT,content TEXT,created_at TIMESTAMPTZ DEFAULT now());
